<?php
require_once __DIR__.'/../includes/bootstrap.php';admin_required();$pdo=db();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$ev=['title'=>'','description'=>'','category'=>'Technology','venue'=>'','event_date'=>'','capacity'=>50,'status'=>'draft'];if($id){$s=$pdo->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$old=$s->fetch();if(!$old){http_response_code(404);exit('Event not found.');}$ev=$old;}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();foreach(['title','description','category','venue','status'] as $k)$ev[$k]=trim((string)($_POST[$k]??''));$ev['capacity']=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT);$raw=(string)($_POST['event_date']??'');$dt=DateTime::createFromFormat('Y-m-d\TH:i',$raw);if(mb_strlen($ev['title'])<3)$errors[]='Title must be at least 3 characters.';if(mb_strlen($ev['description'])<10)$errors[]='Description must be at least 10 characters.';if($ev['venue']==='')$errors[]='Venue is required.';if(!$dt)$errors[]='Choose a valid date and time.';if(!is_int($ev['capacity'])||$ev['capacity']<1)$errors[]='Capacity must be at least 1.';if(!in_array($ev['status'],['draft','published','cancelled'],true))$errors[]='Invalid status.';if(!$errors){$date=$dt->format('Y-m-d H:i:s');if($id){$s=$pdo->prepare('UPDATE events SET title=?,description=?,category=?,venue=?,event_date=?,capacity=?,status=? WHERE id=?');$s->execute([$ev['title'],$ev['description'],$ev['category'],$ev['venue'],$date,$ev['capacity'],$ev['status'],$id]);flash('Event updated.');}else{$s=$pdo->prepare('INSERT INTO events(title,description,category,venue,event_date,capacity,status,created_by) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$ev['title'],$ev['description'],$ev['category'],$ev['venue'],$date,$ev['capacity'],$ev['status'],user()['id']]);flash('Event created.');}go('index.php');}}
$dateValue=$ev['event_date']?date('Y-m-d\TH:i',strtotime($ev['event_date'])):'';$pageTitle=$id?'Edit event':'Create event';require __DIR__.'/../includes/header.php';?><div class="auth-wrap"><div class="auth-card"><a href="index.php">← Admin dashboard</a><h1 class="h2 fw-bold mt-3"><?=$id?'Edit event':'Create event'?></h1><?php if($errors):?><div class="alert alert-danger"><?php foreach($errors as $er):?><div><?=e($er)?></div><?php endforeach;?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(token())?>"><div class="mb-3"><label class="form-label">Title</label><input class="form-control" name="title" maxlength="160" required value="<?=e($ev['title'])?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="4" required><?=e($ev['description'])?></textarea></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Category</label><select class="form-select" name="category"><?php foreach(['Technology','Workshop','Cultural','Sports','Career','General'] as $c):?><option <?=($ev['category']===$c?'selected':'')?>><?=e($c)?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label">Capacity</label><input class="form-control" type="number" name="capacity" min="1" required value="<?=e((string)$ev['capacity'])?>"></div></div><div class="mb-3"><label class="form-label">Venue</label><input class="form-control" name="venue" required value="<?=e($ev['venue'])?>"></div><div class="row"><div class="col-md-7 mb-3"><label class="form-label">Date and time</label><input class="form-control" type="datetime-local" name="event_date" required value="<?=e($dateValue)?>"></div><div class="col-md-5 mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['draft','published','cancelled'] as $s):?><option <?=($ev['status']===$s?'selected':'')?>><?=e($s)?></option><?php endforeach;?></select></div></div><button class="btn btn-primary w-100">Save event</button></form></div></div><?php require __DIR__.'/../includes/footer.php';?>